from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import product
import heapq


def _ledger(data, priority, tax_base, refunds):
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        if priority == "revision_first":
            key = (event.get("revision", 0), position)
        else:
            key = (sequence, event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        mode = data["rounding"]
        net = rounded(raw * (10000 - discount), 10000, mode)
        base = raw if tax_base == "original" else net
        tax = rounded(base * event.get("tax_bp", 0), 10000, mode)
        total = net + tax
        if refunds and event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _resolver(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    versions = {name: {row["version"]: row for row in rows}
                for name, rows in packages.items()}
    domains = []
    for name in names:
        allowed = [v for v in versions[name]
                   if v not in blocked.get(name, [])
                   and (name not in pins or pins[name] == v)]
        domains.append([-1] + sorted(allowed))

    best_vector = None
    best = None
    for vector in product(*domains):
        selected = {name: version for name, version in zip(names, vector)
                    if version != -1}
        valid = True
        for name, bounds in data["roots"].items():
            version = selected.get(name)
            if version is None or not bounds[0] <= version <= bounds[1]:
                valid = False
                break
        if not valid:
            continue

        graph = {name: [] for name in selected}
        for name, version in selected.items():
            row = versions[name][version]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                target_version = selected.get(target)
                if target_version is None or not dep["min"] <= target_version <= dep["max"]:
                    valid = False
                    break
                graph[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        # Only packages reachable through root dependency closure may be installed.
        reachable = set()
        stack = list(data["roots"])
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            if name in graph:
                stack.extend(graph[name])
        if reachable != set(selected):
            continue

        finished, active = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in graph[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in graph):
            continue
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best = selected
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    available = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None

    for indexes in product((0, 1), repeat=len(available)):
        if sum(indexes) != k:
            continue
        selected = [job for job, take in zip(available, indexes) if take]
        ids = {job["id"] for job in selected}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selected:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        active_ends = []
        feasible = True
        for job in sorted(selected, key=lambda item: (item["start"], item["end"], item["id"])):
            while active_ends and active_ends[0] <= job["start"]:
                heapq.heappop(active_ends)
            heapq.heappush(active_ends, job["end"])
            if len(active_ends) > 2:
                feasible = False
                break
        if not feasible:
            continue

        value = sum(job["value"] for job in selected)
        ordered_ids = tuple(sorted(ids))
        if (best_value is None or value > best_value or
                (value == best_value and ordered_ids > best_ids)):
            best_value, best_ids = value, ordered_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _routes(data):
    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bit_for.get(data["source"], 0)
    start_state = (data["source"], initial_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"],) + start_state]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [(edge["duration"], remaining)]
            if remaining:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                durations.append((duration, remaining - 1))
            for duration, next_remaining in durations:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                next_state = (next_node, next_mask, next_remaining)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time,) + next_state)
    return {"arrival": None}


SOLVERS = {
    "component_01": lambda data: _ledger(data, "revision_first", "original", True),
    "component_02": lambda data: _ledger(data, "sequence_first", "original", True),
    "component_03": lambda data: _ledger(data, "revision_first", "discounted", True),
    "component_04": lambda data: _ledger(data, "sequence_first", "discounted", True),
    "component_05": lambda data: _ledger(data, "revision_first", "original", True),
    "component_06": _resolver,
    "component_07": _jobs,
    "component_08": _routes,
}
